    "import torch\n",
    "from torchvision import transforms, models\n",
    "from PIL import Image\n",
    "import matplotlib.pyplot as plt\n",
    "import torch.nn as nn\n",
    "from pathlib import Path\n",
    "\n",
    "# تنظیمات\n",
    "device = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n",
    "\n",
    "# لود مدل\n",
    "model = models.efficientnet_b0(weights=None)\n",
    "num_features = model.classifier[1].in_features\n",
    "model.classifier[1] = nn.Linear(num_features, 7)\n",
    "model.load_state_dict(torch.load('best_efficientnet_emotion.pth', map_location=device))\n",
    "model = model.to(device)\n",
    "model.eval()\n",
    "\n",
    "# Transform\n",
    "transform = transforms.Compose([\n",
    "    transforms.Resize((224, 224)),\n",
    "    transforms.Grayscale(num_output_channels=3),\n",
    "    transforms.ToTensor(),\n",
    "    transforms.Normalize(mean=[0.485, 0.456, 0.406], std=[0.229, 0.224, 0.225])\n",
    "])\n",
    "\n",
    "class_names = ['Angry', 'Disgust', 'Fear', 'Happy', 'Sad', 'Surprise', 'Neutral']\n",
    "\n",
    "# آدرس تصویر (تغییر دهید)\n",
    "image_path = \"test_image.jpg\"  # یا مسیر کامل\n",
    "\n",
    "try:\n",
    "    # خواندن تصویر\n",
    "    img = Image.open(image_path).convert('RGB')\n",
    "    \n",
    "    # پردازش\n",
    "    input_tensor = transform(img).unsqueeze(0).to(device)\n",
    "    \n",
    "    # پیش‌بینی\n",
    "    with torch.no_grad():\n",
    "        output = model(input_tensor)\n",
    "        probabilities = torch.nn.functional.softmax(output, dim=1)[0]\n",
    "        _, predicted_idx = torch.max(output, 1)\n",
    "        \n",
    "    predicted_emotion = class_names[predicted_idx.item()]\n",
    "    confidence = probabilities[predicted_idx.item()].item() * 100\n",
    "    \n",
    "    # نمایش نتیجه\n",
    "    print(\"=\"*60)\n",
    "    print(f\"✅ احساس تشخیص داده شده: {predicted_emotion}\")\n",
    "    print(f\"🎯 میزان اطمینان: {confidence:.2f}%\")\n",
    "    print(\"=\"*60)\n",
    "    \n",
    "    # نمایش تمام احتمالات\n",
    "    print(\"\\n📊 احتمالات برای تمام احساسات:\")\n",
    "    for i, (name, prob) in enumerate(zip(class_names, probabilities)):\n",
    "        bar = \"█\" * int(prob.item() * 50)\n",
    "        print(f\"   {name:10s}: {prob.item()*100:5.2f}% {bar}\")\n",
    "    \n",
    "    # نمایش تصویر\n",
    "    plt.figure(figsize=(6, 6))\n",
    "    plt.imshow(img)\n",
    "    plt.title(f\"Prediction: {predicted_emotion}\\nConfidence: {confidence:.1f}%\", \n",
    "              fontsize=16, fontweight='bold', color='green')\n",
    "    plt.axis('off')\n",
    "    plt.show()\n",
    "    \n",
    "except FileNotFoundError:\n",
    "    print(f\"❌ خطا: فایل '{image_path}' پیدا نشد!\")\n",
    "    print(\"💡 لطفاً یک تصویر چهره در همین پوشه قرار دهید و نام آن را تغییر دهید.\")\n",
    "except Exception as e:\n",
    "    print(f\"❌ خطا: {e}\")"
